$ErrorActionPreference='Stop';$code=1
$names=@('APP_ENV','SUPABASE_URL','EDUCATIVO_API_URL','EDUCATIVO_PUBLIC_KEY','EDUCATIVO_A_ID','EDUCATIVO_B_ID','EDUCATIVO_A_TOKEN','EDUCATIVO_B_TOKEN','EDUCATIVO_A_UNIDAD_ID','EDUCATIVO_B_UNIDAD_ID','EDUCATIVO_SYNTHETIC_USERS','EDUCATIVO_LOCAL_API_VERIFIED','EDUCATIVO_RECOVERY_RUN_ID')
function Set-Private([string]$n,[string]$label){$s=Read-Host $label -AsSecureString;$p=[Runtime.InteropServices.Marshal]::SecureStringToBSTR($s);try{[Environment]::SetEnvironmentVariable($n,[Runtime.InteropServices.Marshal]::PtrToStringBSTR($p),'Process')}finally{[Runtime.InteropServices.Marshal]::ZeroFreeBSTR($p);$s.Dispose()}}
try{$env:APP_ENV='test';$env:SUPABASE_URL='https://gwdtlbisykzzplgzczzq.supabase.co';$env:EDUCATIVO_API_URL='http://127.0.0.1:3000';$env:EDUCATIVO_LOCAL_API_VERIFIED='confirmed';$env:EDUCATIVO_SYNTHETIC_USERS=Read-Host 'A/B sinteticos exclusivos: confirmed';$env:EDUCATIVO_RECOVERY_RUN_ID=Read-Host 'runId 03D2C';Set-Private 'EDUCATIVO_PUBLIC_KEY' 'Clave PUBLICA test';foreach($a in @('A','B')){Set-Private "EDUCATIVO_${a}_ID" "UUID usuario $a";Set-Private "EDUCATIVO_${a}_TOKEN" "Token $a";Set-Private "EDUCATIVO_${a}_UNIDAD_ID" "UUID unidad sintetica propia $a"};& node (Join-Path $PSScriptRoot 'technical-jobs-recovery-run.js');$code=$LASTEXITCODE}catch{$code=1}finally{foreach($n in $names){[Environment]::SetEnvironmentVariable($n,$null,'Process')}};exit $code
